def decimal_to_binary(decimal):
    """Convert a non-negative integer to its binary representation as a string,
    surrounded by 'db' characters."""
    if decimal == 0:
        return 'db0db'
    elif decimal == 1:
        return 'db1db'
    binary_str = ''
    while decimal > 0:
        binary_str = str(decimal % 2) + binary_str
        decimal //= 2
    return f'db{binary_str}db'

